/* RAVN South interactive site prototype. Data remains in the visitor's browser. */
const A='./assets/';
// Coach Jill chat is not stored in localStorage; API key and invitation code are never included in JS.
let jillHistory=[], jillBusy=false;
let jackHistory=[], jackBusy=false;
const $=(s)=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'⌂',training:'◆',nutrition:'◉',mentality:'◇',vault:'♧',arena:'♛',dashboard:'▣'};
const nav=[['/','Home'],['/vault','RAVN Vault'],['/fitness-programmes','Training'],['/nutrition','Nutrition'],['/mentality','Five Pillars'],['/arena','RAVN Arena'],['/coaches','Coaches'],['/dashboard','Dashboard']];
const defaults={name:'RAVN Member',joined:false,tier:'Free',points:0,logs:[],program:'',posts:[],likes:[],groups:[],messages:[],nutrition:[],stories:[],gifts:[],buddies:[],searchTerm:'',checkinText:'',goals:[],visibility:'members',email:'',notices:true};
function safelyLoadDemo(){try{return JSON.parse(localStorage.getItem('ravn-full-test-v1')||'{}')||{}}catch(e){return {}}}
let s={...defaults,...safelyLoadDemo()};
function save(){try{localStorage.setItem('ravn-full-test-v1',JSON.stringify(s))}catch(e){/* storage may be blocked in local preview */}}
function path(){try{return decodeURI(location.hash.slice(1)||'/').split('?')[0].replace(/\/$/,'')||'/'}catch{return '/not-found'}}
function navto(p){location.hash='#'+p}
function toast(msg){let old=$('.toast');if(old)old.remove();let d=document.createElement('div');d.className='toast';d.textContent=msg;document.body.appendChild(d);setTimeout(()=>d.remove(),2900)}
const today=()=>new Date().toISOString().slice(0,10);
const month=()=>new Date().toISOString().slice(0,7);
function logAction(key,points,label,scope='day'){
 if(!s.joined){toast('Enter member demo first to track achievements.');navto('/login');return}
 let ref=scope==='day'?today():scope==='month'?month():'once';
 if(s.logs.some(x=>x.key===key&&x.ref===ref)){toast('Already recorded for this period — consistency counts.');return}
 s.logs.unshift({key,points,label,ref,date:new Date().toISOString()});s.points+=points;
 if(points>=20 && !s.logs.some(x=>x.key==='first-accolade')){s.logs.unshift({key:'first-accolade',points:25,label:'First accolade unlocked',ref:'once',date:new Date().toISOString()});s.points+=25}
 save();toast('+'+points+' points · '+label);render();
}
const logged=(key)=>s.logs.some(l=>l.key===key&&l.ref===today());
const logsMonth=()=>s.logs.filter(l=>l.date.slice(0,7)===month());
const monthly=()=>logsMonth().reduce((n,l)=>n+l.points,0);
const level=()=>Math.floor(s.points/500)+1;
const pct=()=>Math.min(100,Math.round((s.points%500)/5));
const avatar=n=>`<span class="avatar">${esc(n).split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase()}</span>`;
const btn=(href,label,outline=false)=>`<a class="${outline?'btn-outline':'btn'}" href="#${href}">${label}</a>`;
const pageHero=(title,sub,desc)=>`<section class="hero-custom"><div class="wrap"><div class="eyebrow">RAVN SOUTH · DO IT. PROVE IT.</div><h1>${title}</h1><div class="eyebrow" style="color:#e5c39b">${sub}</div><p class="lead">${desc}</p></div></section>`;
const section=(title,body,after='')=>`<section class="section"><div class="wrap"><div class="sectionhead"><h2>${title}</h2>${after}</div>${body}</div></section>`;
const card=(html,cls='')=>`<article class="card ${cls}">${html}</article>`;
const footlinks=[['/about','Our Story'],['/media','Media'],['/coaches','Meet the Coaches'],['/contact','Contact'],['/faq','FAQs'],['/privacy','Privacy'],['/terms','Terms']];
function header(){let p=path();return `<header class="topbar"><div class="topinner"><a class="brand" href="#/"><img class="brand-logo" src="${A}ravn-master-logo-tight.png" alt="RAVN SOUTH"></a><nav class="nav" id="mainnav">${nav.map(([u,n])=>`<a class="${u===p||(u==='/vault'&&p==='/profile')||(u!=='/'&&p.startsWith(u+'/'))||(u==='/coaches'&&p.startsWith('/coach/'))?'active':''}" href="#${u}">${n}</a>`).join('')}</nav><div class="topactions"><a class="btn-soft small account-link" href="#${s.joined?'/dashboard':'/login'}">${s.joined?'MY DASHBOARD':'MEMBER LOGIN'}</a><button type="button" class="btn-soft small menu-btn" data-action="menu" aria-label="Open navigation">☰</button></div></div></header>`}
function footer(){return `<footer class="footer"><div class="wrap"><div class="footer-cols"><div><div class="brand"><img class="brand-logo" src="${A}ravn-master-logo.png" alt="RAVN SOUTH — DO IT. PROVE IT."></div><p>Do it. Prove it.<br>Every step is an achievement.</p></div><div><h4>Explore</h4>${[['/vault','The Vault'],['/mentality','Five Pillars'],['/coaches','Coaches'],['/coach/jack','Coach Jack Chat'],['/coach/jill','Coach Jill Chat']].map(([p,n])=>`<a href="#${p}">${n}</a>`).join('')}</div><div><h4>Members</h4>${[['/dashboard','Dashboard'],['/achievements','Achievements'],['/settings','Settings'],['/goals','Goals']].map(([p,n])=>`<a href="#${p}">${n}</a>`).join('')}</div><div><h4>Information</h4>${footlinks.map(([p,n])=>`<a href="#${p}">${n}</a>`).join('')}</div></div><div class="foot-bottom">© ${new Date().getFullYear()} RAVN South · Interactive development prototype · Demo progress stored only in this browser. No live accounts, payments or shared data.</div></div></footer>`}
function memberNotice(){return !s.joined?`<div class="notice">This is a working prototype. <a href="#/login" style="text-decoration:underline">Enter the member demo</a> to try progress tracking. Your changes are saved on this device only.</div>`:''}
function progressCard(){return card(`<div class="eyebrow">YOUR PROGRESSION</div><h3>${esc(s.name)}</h3><div class="stats" style="grid-template-columns:repeat(2,1fr)"><div class="stat"><strong>${s.points}</strong><span>Total points</span></div><div class="stat"><strong>${level()}</strong><span>Level</span></div></div><div class="progress" style="margin-top:22px"><span style="width:${pct()}%"></span></div><small>${s.points%500} / 500 points to next level</small><div class="line"></div>${btn('/dashboard','View dashboard')}`)}
function home(){return `<section class="hero-crop hero-short clickable-hero"><img src="${A}home-hero.webp" alt="RAVN South with Jack and Jill"><a class="hero-hotspot home-hotspot" href="#/signup" aria-label="Join the free community"></a></section>`+section('YOUR COMMUNITY. YOUR STORY.',card('<h3>THE VAULT IS FREE</h3><p>Share your journey, connect with others and celebrate every honest step. No subscription or payment is required.</p>'+btn('/vault','Explore The Vault')+' '+btn('/signup','Join free',true)))+section('THE FIVE PILLARS',`<img src="${A}pillars.webp" style="width:100%" alt="Motivation, Determination, Gratification, Sustainability, Maintenance"><p>Build habits that fit alongside your health, relationships, family and work.</p>${btn('/mentality','Explore the Five Pillars',true)}`)+section('MAKE IT YOURS',`<div class="grid cols3">${card('<h3>Share your story</h3><p>Updates, photos and encouragement from your community.</p>'+btn('/vault/feed','Community feed',true))}${card('<h3>Connect</h3><p>Find people with shared interests and keep in touch.</p>'+btn('/vault/buddies','Find buddies',true))}${card('<h3>Your own progress</h3><p>Personal goals and reflection, at your own pace.</p>'+btn('/dashboard','My dashboard',true))}</div>`)+section('EXPLORE THE FULL SITE',`<div class="grid cols3">${card('<h3>TRAINING</h3>'+btn('/fitness-programmes','Browse programmes'))}${card('<h3>NUTRITION</h3>'+btn('/nutrition','Explore meal plans'))}${card('<h3>RAVN ARENA</h3>'+btn('/arena','Open Arena'))}</div>`)}
const programData=[];
function training(){return fitnessLanding()}
function trainingDetail(id){return fitnessDetail(id)}
function nutrition(){return window.RavnNutrition.hub()}
function rotation(){return window.RavnNutrition.rotation()}
function nutritionDetail(d,g,v){return window.RavnNutrition.plan(d,g,v)}
function nutritionSnacks(){return window.RavnNutrition.snacks()}
function nutritionShopping(){return window.RavnNutrition.shopping()}
const pillars=[['MOTIVATION','The spark that starts it.','Motivation is personal. Understand your reason to begin.','pillar-motivation'],['DETERMINATION','The grit that keeps you.','Show up even when the initial excitement fades.','pillar-determination'],['GRATIFICATION','The reward that drives you.','Recognise progress without letting satisfaction stop the effort.','pillar-gratification'],['SUSTAINABILITY','The balance that lasts.','Your development should work alongside health, relationships, home and work.','pillar-sustainability'],['MAINTENANCE','The habits that protect you.','Build the actions that help you protect what you have achieved.','pillar-maintenance']];
function mentality(){return `<section class="hero-custom mentality-hero"><div class="wrap mentality-hero-grid"><div class="mentality-hero-copy"><div class="eyebrow">RAVN SOUTH · DO IT. PROVE IT.</div><h1>MENTALITY<br><span>THE FIVE PILLARS</span></h1><div class="eyebrow mentality-kicker">A STRONG MIND BUILDS A STRONGER LIFE.</div><p class="lead">Real progress begins with understanding your reasons, your challenges and the steps you can genuinely sustain.</p><p>Meet Coach Jill, your guide through the Five Pillars of Strength. No judgement. No perfect starting point. Every step counts.</p><div class="mentality-hero-actions">${btn('/coach/jill','Talk with Coach Jill')}${btn('/mentality/motivation','Explore the pillars',true)}</div><p class="mini mentality-demo-note">Coach Jill's AI chat is an opt-in pilot and needs secure private access. It is not therapy.</p></div><a class="mentality-jill-frame" href="#/coach/jill" aria-label="Open Coach Jill's mentality coaching conversation"><img src="${A}coach-jill-portrait.webp" alt="Coach Jill — RAVN South mentality coach" loading="eager"><div class="mentality-jill-name"><span>YOUR MENTALITY COACH</span><strong>COACH JILL</strong><small>Understand your why. Find your way forward. →</small></div></a></div></section>`+section('EXPLORE THE FIVE PILLARS',`<div class="grid cols5">${pillars.map(([n,t,d,img])=>`<a class="feature-card card" href="#/mentality/${n.toLowerCase()}"><img src="${A+img}.webp" alt="${n} engraved stone pillar"><div class="body"><h3>${n}</h3><div class="eyebrow">${t}</div><p>${d}</p></div></a>`).join('')}</div>`)+section('YOUR MENTALITY JOURNEY',`<div class="mentality-journey-grid">${card(`<div class="eyebrow">START THE CONVERSATION</div><h3>Understand your own reasons</h3><p>Jill's role is to listen, ask open questions and help you find what matters to you — whether that's health, confidence, enjoyment or your own sense of achievement.</p><p>She'll help you recognise the effort in every attempt and build a routine that works alongside family, relationships, work and health.</p>${btn('/coach/jill','Talk with Coach Jill')}<p class="mini" style="margin-top:14px">AI conversations require pilot access and a server connection; no clinical care is provided.</p>`)}${card(`<div class="eyebrow">THE NEXT STEP IS YOURS</div><div class="mentality-next-point"><span>01</span><div><h3>Find your motivation</h3><p>Discover the personal reason behind your goal.</p></div></div><div class="mentality-next-point"><span>02</span><div><h3>Recognise your progress</h3><p>Even an attempt that doesn't work out can move you forward.</p></div></div><div class="mentality-next-point"><span>03</span><div><h3>Build lasting balance</h3><p>Growth should support your life, not overwhelm it.</p></div></div>`)} </div>`) }
function pillarDetail(slug){let p=pillars.find(x=>x[0].toLowerCase()===slug);if(!p)return notFound();return pageHero(p[0],p[1].toUpperCase(),p[2])+section('PUT IT INTO PRACTICE',`<div class="grid cols2">${card(`<img src="${A+p[3]}.webp" class="banner-img" alt="${p[0]} pillar"><h3 style="margin-top:16px">${p[0]} IN ACTION</h3><p>${p[2]}</p><p>What would one small action in this area look like today?</p><a class="btn-outline" href="#/mentality">All Five Pillars</a>`)}${card(`<h3>YOUR REFLECTION</h3><label class="field"><span>What is one step you can take?</span><textarea id="reflect" rows="5" placeholder="Write your next step..."></textarea></label><button class="btn" data-action="reflect" data-pillar="${p[0]}">Save reflection</button><p class="mini">Saved privately to your account when signed in.</p>`)}</div>`) }
function vault(){return `<section class="hero-crop clickable-hero"><img src="${A}vault-hero.webp" alt="RAVN Vault original hero design"><a class="hero-hotspot vault-hotspot" href="#/vault/feed" aria-label="Join RAVN Vault community"></a></section>${section('CONNECT · SHARE · GROW',`<div class="grid cols5">${[['♧','Profiles','/profile'],['◌','Messaging','/messages'],['♧','Groups','/groups'],['▣','Stories & Posts','/vault/feed'],['♧','Gifting & Badges','/achievements']].map(([ic,n,p])=>card(`<div class="symbol">${ic}</div><h3>${n}</h3>${btn(p,'Explore',true)}`)).join('')}</div>`)}${section('LATEST FROM THE VAULT',feedInner(),btn('/vault/feed','See full community feed',true))}${section('MORE WAYS TO CONNECT',`<div class="grid cols3">${[['◈','MEMBER STORIES','/vault/stories','Short updates from everyday journeys.'],['✦','GIFTING','/vault/gifting','Recognise and encourage another member.'],['♧','TRAINING BUDDIES','/vault/buddies','Connect around shared training goals.']].map(([ic,t,href,sub])=>card(`<div class="symbol">${ic}</div><h3>${t}</h3><p>${sub}</p>${btn(href,'Explore',true)}`)).join('')}</div>`)}`}
const samplePosts=[{id:'s1',name:'Hannah P.',text:'Small win: showed up for the gym even when I nearly turned around. That counts.',likes:24,age:'2 hours ago'},{id:'s2',name:'Mark D.',text:'Meal prep finished for the week. Keeping things simple and sustainable.',likes:18,age:'4 hours ago'},{id:'s3',name:'Emma L.',text:'Feeling more confident with my training form this month.',likes:38,age:'Yesterday'}];
function feedInner(full=false){const postlist=[...s.posts.filter(x=>x.visibility!=='private'),...samplePosts].slice(0,full?99:3);return `<div class="grid cols2"><div>${memberNotice()}${card(`<h3>SHARE YOUR JOURNEY</h3><label class="field"><span>Your update</span><textarea id="posttext" maxlength="800" rows="3" placeholder="Share a small win, question or update..."></textarea></label><button class="btn" data-action="post">Share post</button><p class="mini">Demo posts are visible only in your own browser.</p>`)}<div style="height:18px"></div>${postlist.map(p=>card(`<div class="post-header">${avatar(p.name)}<div><strong>${esc(s.posts.some(x=>x.id===p.id)?s.name:p.name)}</strong><div class="mini">${p.age||'Just now'}</div></div></div><div class="post-body">${esc(p.text)}</div>${vpImage(p.photo)?`<img class="vp-post-photo" src="${p.photo}" alt="Member journey photo" loading="lazy">`:''}<div class="post-tools"><button data-action="like" data-id="${p.id}">${s.likes.includes(p.id)?'♥ Liked':'♡ Like'} · ${p.likes+(s.likes.includes(p.id)?1:0)}</button></div>`,'post')).join('')}</div><div>${card(`<h3>POPULAR TOPICS</h3><div class="list">${['Training & Workouts','Nutrition & Recipes','Mindset & Motivation','Progress & Achievements','General Chat','Challenges'].map(x=>`<div class="list-row"><span>${x}</span><a href="#/groups">↗</a></div>`).join('')}</div>`)}<div style="height:18px"></div>${card(`<h3>IT’S NOT A RACE.</h3><div class="quote">IT’S YOUR JOURNEY.</div><p>Consistency. Effort. Real progress.</p>${btn('/groups','Find your tribe',true)}`)}</div></div>`}
function feed(){return pageHero('VAULT COMMUNITY','REAL PEOPLE. REAL PROGRESS. TOGETHER.','Celebrate wins, ask questions and support each other.')+section('COMMUNITY FEED',feedInner(true))}
const leaderboard=[['Sarah T.',1245,12,4],['Mark D.',1120,10,3],['Emma L.',980,9,3],['James K.',910,8,2],['Hannah P.',840,7,2]];
function rankRows(period='month'){let rows=[...leaderboard.map(x=>({name:x[0],points:x[1],badges:x[2],trophies:x[3]}))];if(s.joined)rows.push({name:s.name+' (you)',points:period==='month'?monthly():s.points,badges:Math.floor(s.points/200),trophies:Math.floor(s.points/1000),self:true});rows.sort((a,b)=>b.points-a.points);return rows.map((r,i)=>`<tr class="${r.self?'highlight':''}"><td>${i===0?'🥇':i===1?'🥈':i===2?'🥉':'#'+(i+1)}</td><td>${esc(r.name)}</td><td>${r.points.toLocaleString()}</td><td>${r.badges}</td><td>${r.trophies}</td></tr>`).join('')}
function arena(){
 const features=[['✦','POINTS','Daily actions and achievements'],['♧','ACCOLADES','Smaller milestones'],['⬡','BADGES','Bigger achievements'],['🏆','TROPHIES','Major milestones'],['♙','RANKINGS','Climb the leaderboard']];
 const featureCards='<div class="grid cols5">'+features.map(x=>card('<div class="symbol">'+x[0]+'</div><h3>'+x[1]+'</h3><p>'+x[2]+'</p>')).join('')+'</div>';
 const panel=card('<div class="eyebrow">MEMBERS ONLY · MONTHLY COMPETITION</div><div class="tabs"><button class="tab active" data-action="leader-tab" data-period="month">This month</button><button class="tab" data-action="leader-tab" data-period="all">All time</button></div><div class="tablewrap"><table><thead><tr><th>Rank</th><th>Member</th><th>Points</th><th>Badges</th><th>Trophies</th></tr></thead><tbody id="leaderrows">'+rankRows()+'</tbody></table></div><p class="mini">Other member names and scores are illustrative, not genuine rankings.</p>');
 const scoring=card('<div class="eyebrow">HOW SCORING WORKS</div><h3>Accountability creates achievement</h3>'+[['Training session',10],['Nutrition target',10],['Accountability',5],['Monthly challenge',20],['First accolade',25]].map(x=>'<div class="list-row"><span>'+x[0]+'</span><strong style="color:var(--green)">+'+x[1]+' pts</strong></div>').join('')+'<div class="line"></div><h3>YOUR PROGRESS</h3><p>'+s.points+' points · Level '+level()+'</p>'+btn('/dashboard','My dashboard',true));
 const legacy='<div class="grid cols2">'+card('<h3>HALL OF FAME</h3><p>Permanent recognition for consistent achievers.</p>'+btn('/hall-of-fame','See Hall of Fame',true))+card('<h3>CHALLENGES</h3><p>Earn legitimate milestones through consistency.</p>'+btn('/challenges','Explore challenges',true))+'</div>';
 return '<section class="hero-crop clickable-hero"><img src="'+A+'arena-hero.webp" alt="RAVN Arena original hero"><a class="hero-hotspot arena-hotspot" href="#/arena/leaderboard" aria-label="View members leaderboard"></a></section>'+section('COMPETE · PROGRESS · EARN',featureCards)+section('MONTHLY LEADERBOARD',s.joined?'<div class="grid cols2">'+panel+scoring+'</div>':card('<div class="eyebrow">MEMBERS ONLY</div><h3>The leaderboard is waiting for you.</h3><p>Sign up for a free member profile to enter the Arena and see the rankings.</p>'+btn('/signup','Join RAVN South')) )+section('BUILD YOUR LEGACY',legacy);
}
function arenaLeaderboard(){return pageHero('ARENA LEADERBOARD','MEMBERS ONLY · CONSISTENCY WINS.','Every genuine step has value. Compete through accountability and achievements.')+section('CURRENT STANDINGS',s.joined?card('<div class="eyebrow">DEMONSTRATION RANKINGS · '+month()+'</div><div class="tabs"><button class="tab active" data-action="leader-tab" data-period="month">This month</button><button class="tab" data-action="leader-tab" data-period="all">All time</button></div><div class="tablewrap"><table><thead><tr><th>Rank</th><th>Member</th><th>Points</th><th>Badges</th><th>Trophies</th></tr></thead><tbody id="leaderrows">'+rankRows()+'</tbody></table></div><p class="mini">Sample competitors are fictitious. Your demo points are only stored on this device.</p>'):card('<h3>MEMBERS-ONLY STANDINGS</h3><p>Create a free demo profile to enter the Arena.</p>'+btn('/signup','Join free')))+section('THE BIGGER PICTURE',card('<h3>LONG-TERM CONSISTENCY</h3><p>Monthly standings begin again. The Hall of Fame is where members build their legacy.</p>'+btn('/hall-of-fame','Hall of Fame',true)))}
function hall(){const honours=[['✦','CONSISTENCY','Recognised for sustained effort'],['🏆','ACHIEVEMENT','Recognised for major milestones'],['♛','COMMUNITY','Recognised for encouraging others']];const inner='<div class="grid cols3">'+honours.map(h=>card('<div class="symbol">'+h[0]+'</div><h3>'+h[1]+'</h3><p>'+h[2]+'</p><span class="tag">Future member honours</span>')).join('')+'</div><div class="line"></div><p>No genuine Hall of Fame winners have been recorded in this prototype. Members will be featured once verifiable competition history exists.</p>';return pageHero('HALL OF FAME','CONSISTENCY BUILDS A LEGACY.','The Arena starts afresh every month. The Hall of Fame celebrates long-term achievement.')+section('FOUNDING HONOURS',s.joined?inner:card('<h3>Members-only recognition</h3><p>Enter the member area to view the Hall of Fame.</p>'+btn('/signup','Join RAVN South')),btn('/arena','Back to Arena',true))}

function challenges(){
 const items=[['Check in today','Reflect on your effort','checkin',5],['Complete planned training','Follow through with training','training',10],['Monthly consistency challenge','Show up this month','challenge',20]];
 const content='<div class="grid cols3">'+items.map(([t,d,key,v])=>card('<div class="symbol">✦</div><h3>'+t+'</h3><p>'+d+'</p><button class="btn-outline" data-action="log" data-key="'+key+'" data-points="'+v+'" data-label="'+t+'" '+((key==='challenge'?s.logs.some(x=>x.key==='challenge'&&x.ref===month()):logged(key))?'disabled':'')+'>Record achievement · +'+v+' pts</button>')).join('')+'</div><p class="mini">Production scores will require verification.</p>';
 return pageHero('CHALLENGES','SHOW UP. KEEP GOING.','Recognise consistency, not strength or appearance.')+section('YOUR CHALLENGES',content)
}
function achievements(){let n=s.logs.length;return pageHero('YOUR ACHIEVEMENTS','EVERY STEP IS AN ACHIEVEMENT.','Accolades for smaller milestones, badges for bigger achievements and trophies for major victories.')+section('YOUR COLLECTION',`${memberNotice()}<div class="stats">${[['Total Points',s.points],['Accolades',s.logs.filter(l=>l.key==='first-accolade').length],['Badges',[s.points>=100,s.logs.filter(l=>l.key==='training').length>=5,s.logs.filter(l=>l.key==='nutrition').length>=5].filter(Boolean).length],['Trophies',s.points>=1000?1:0]].map(([l,v])=>card(`<div class="stat"><strong>${v}</strong><span>${l}</span></div>`)).join('')}</div><div class="line"></div><div class="badge-grid">${[['✦','First Step',s.points>=5],['♧','Getting Started',s.points>=25],['⬡','Determined',s.points>=100],['🏆','Dedicated',s.points>=500],['✦','Nutrition Focus',s.logs.some(x=>x.key==='nutrition')],['⬡','Training Habit',s.logs.some(x=>x.key==='training')],['♛','Arena Challenger',s.logs.some(x=>x.key==='challenge')],['🏆','1,000 Points',s.points>=1000]].map(([i,l,has])=>`<div class="badgeitem ${has?'':'badgelocked'}"><div class="symbol">${i}</div><strong>${l}</strong><div class="mini">${has?'Unlocked':'Locked'}</div></div>`).join('')}</div>`)+section('YOUR ACHIEVEMENT HISTORY',s.logs.length?card(`<div class="list">${s.logs.map(l=>`<div class="list-row"><span>${esc(l.label)} <div class="mini">${new Date(l.date).toLocaleDateString('en-GB')}</div></span><strong>+${l.points}</strong></div>`).join('')}</div>`):card(`<div class="empty">No achievements yet. Start with a daily check-in.</div>${btn('/accountability','Record your first step')}`))}
function dashboard(){return pageHero('MEMBER DASHBOARD','YOUR JOURNEY. YOUR PROGRESS.','Training, nutrition, mentality and community — everything in one personal space.')+section('YOUR SPACE',`${memberNotice()}<div class="grid cols3">${progressCard()}${card(`<div class="eyebrow">TODAY’S ACTIONS</div><h3>Build your consistency</h3>${[['training','Training',10],['nutrition','Nutrition',10],['checkin','Accountability',5]].map(([key,l,v])=>`<div class="list-row"><span>${logged(key)?'✓':'○'} ${l}</span><button class="btn-soft small" data-action="log" data-key="${key}" data-points="${v}" data-label="${l} completed" ${logged(key)?'disabled':''}>${logged(key)?'Done':'+'+v+' pts'}</button></div>`).join('')}`)}${card(`<div class="eyebrow">YOUR MEMBERSHIP</div><h3>${esc(s.tier)} member</h3><p>Current programme: ${esc(s.program)}</p>${btn('/membership','Explore membership',true)}<div class="line"></div>${btn('/profile','Edit your profile',true)}`)}</div>`)+section('YOUR PERSONAL TOOLS',`<div class="grid cols4">${[['▣','Accountability','/accountability'],['✓','My Goals','/goals'],['◆','My Programme','/fitness-programmes'],['✦','My Achievements','/achievements'],['♧','Social Profile','/profile'],['◌','Messages','/messages'],['♛','RAVN Arena','/arena'],['◇','Coach Jill','/coach/jill'],['✶','Coach Jack','/coach/jack']].map(([sym,t,p])=>card(`<div class="symbol">${sym}</div><h3>${t}</h3>${btn(p,'Open',true)}`)).join('')}</div>`) }
function accountability(){return pageHero('ACCOUNTABILITY','SMALL ACTIONS. REAL CONSISTENCY.','Measure the effort you put in, not just the outcome.')+section('YOUR DAILY CHECK-IN',`<div class="grid cols2">${card(`<div class="eyebrow">TODAY’S REFLECTION</div><h3>What did you do for yourself today?</h3><label class="field"><span>Your effort, however small</span><textarea id="checkin" rows="5" placeholder="Even if something didn’t go to plan, what did you try?">${esc(s.checkinText)}</textarea></label><button class="btn" data-action="checkin" ${logged('checkin')?'disabled':''}>${logged('checkin')?'✓ Checked in today':'Save check-in'}</button>`)}${card(`<h3>CONSISTENCY COUNTS</h3><p>A missed attempt can still teach something. Record genuine effort, reflect and plan your next step.</p><div class="stats" style="grid-template-columns:1fr 1fr"><div class="stat"><strong>${s.logs.filter(l=>l.key==='checkin').length}</strong><span>Check-ins logged</span></div><div class="stat"><strong>${monthly()}</strong><span>This month's points</span></div></div>${btn('/arena','View the Arena',true)}`)}</div>`) }
function membership(){let tiers=[['Free','£0','Your own space, community profile, Vault social access and starter achievement tracking.'],['Subscription','£9.99','Enhanced dashboard, fuller training and nutrition content, coaching resources and progression tools.'],['Platinum','Future tier','Additional advanced support for members who have earned the relevant progression milestones.']];return pageHero('MEMBERSHIP','YOU ARE INVESTING IN YOURSELF.','Explore the opportunities available at every stage. Advanced programmes are earned through effort, not simply bought.')+section('FIND YOUR PLACE',`<div class="grid cols3 tiers">${tiers.map(([t,price,d])=>card(`<div class="eyebrow">RAVN SOUTH</div><h3>${t.toUpperCase()}</h3><div class="price">${price}${price!=='Future tier'?'<small> / month</small>':''}</div><div class="line"></div><div class="grow"><p>${d}</p>${(t==='Free'?['Community profile','Vault access','Starter progress tracking']:t==='Subscription'?['Expanded dashboard','Training and nutrition resources','More progression tools']:['Long-term advancement','Eligible advanced content','Milestone-based access']).map(x=>`<div class="checkline">✓ ${x}</div>`).join('')}</div><button class="btn" data-action="tier" data-tier="${t}" ${s.tier===t?'disabled':''}>${s.tier===t?'CURRENT TIER':t==='Platinum'?'VIEW ELIGIBILITY':'SELECT '+t.toUpperCase()}</button><p class="mini">${t==='Free'?'No payment required.':t==='Subscription'?'Prototype only — no payment processed.':'Not purchasable in this prototype.'}</p>`)).join('')}</div>`)+section('PROGRESSION CANNOT BE BOUGHT',card(`<h3>EARN YOUR NEXT STAGE</h3><p>Points, accountability, consistency and real milestones unlock progress. Subscription does not let someone skip the work.</p>${btn('/achievements','View your achievements',true)}`)) }
function login(){return pageHero('MEMBER ACCESS','WELCOME BACK.','Explore the connected member experience in demo mode.')+section('ENTER THE DEMO',`<div style="max-width:550px;margin:auto">${card(`<div class="notice">Demo access only: this is not a secure account login and should not be used with real passwords.</div><label class="field"><span>Your display name</span><input id="demoName" maxlength="45" value="${esc(s.name==='RAVN Member'?'Chris':s.name)}" placeholder="e.g. Alex R."></label><button class="btn" data-action="demo-login">Enter full test site →</button><div class="line"></div><p>New here? <a href="#/signup" style="color:var(--green)">Create a demo profile</a></p>`)}</div>`) }
function signup(){return pageHero('START YOUR JOURNEY','EVERY STEP SHOULD FEEL LIKE AN ACHIEVEMENT.','Create a local demo profile, choose your goals and explore RAVN South.')+section('YOUR FIRST STEP',`<div style="max-width:600px;margin:auto">${card(`<label class="field"><span>Your display name</span><input id="signupName" maxlength="45" placeholder="How should members see your name?"></label><label class="field"><span>Your focus</span><select id="signupGoal"><option>Build consistency</option><option>Build strength</option><option>Improve nutrition</option><option>Build confidence</option><option>Support my general wellbeing</option></select></label><button class="btn" data-action="signup">Create demo profile</button><p class="mini">This local demo doesn't collect a password or register you on a live service.</p>`)}</div>`) }
function profile(){return vaultProfile()}
function groups(){let gs=['Strength & Training','Nutrition Together','Mindset & Motivation','New Members','Walkers & Runners','The Accountability Circle'];return pageHero('COMMUNITY GROUPS','FIND YOUR PEOPLE.','Connect with members who share your interests and goals.')+section('DISCOVER GROUPS',`<div class="grid cols3">${gs.map((g,i)=>card(`<div class="symbol">${['♧','◉','◇','✦','♙','▣'][i]}</div><h3>${g}</h3><p>Share ideas, encouragement and small victories with like-minded people.</p><button class="btn-outline" data-action="group" data-name="${esc(g)}">${s.groups.includes(g)?'✓ Joined':'Join group'}</button>`)).join('')}</div><p class="mini" style="margin-top:20px">Group memberships are saved locally. Member-to-member rooms require a shared backend.</p>`) }
function messages(){return pageHero('MESSAGING','CONNECTION STARTS WITH A CONVERSATION.','Preview how your member messaging space will look.')+section('YOUR MESSAGES',`<div class="grid cols2">${card(`<h3>DEMO CONVERSATION</h3><div id="messageChat" class="chat">${[{from:'Jack',text:'Welcome to your RAVN South inbox. Real member messaging will become available when secure accounts are connected.'},...s.messages].map(m=>`<div class="bubble ${m.from==='You'?'me':''}">${esc(m.text)}</div>`).join('')}</div><div class="chatinput"><input id="messageText" placeholder="Write a demo message..." maxlength="400"><button class="btn" data-action="message">Send</button></div>`)}${card(`<h3>PRIVACY FIRST</h3><p>In the finished Vault, members will control who can contact them and what profile information is visible.</p><p class="mini">This messaging panel is local-only: no real message will be sent to another person.</p>${btn('/settings','Privacy settings',true)}`)}</div>`) }
function coachTabs(active=''){return `<nav class="coach-tabs wrap" aria-label="Choose a RAVN South coach"><a href="#/coaches" class="${active==='both'?'active':''}" ${active==='both'?'aria-current="page"':''}>Meet both coaches</a><a href="#/coach/jack" class="${active==='jack'?'active':''}" ${active==='jack'?'aria-current="page"':''}>Coach Jack · Training chat</a><a href="#/coach/jill" class="${active==='jill'?'active':''}" ${active==='jill'?'aria-current="page"':''}>Coach Jill · Mentality chat</a></nav>`}
function coaches(){return pageHero('MEET YOUR COACHES','TWO COACHES. TWO SPECIALITIES. ONE JOURNEY.','Choose the coach who fits your question. With your permission, Jack and Jill can also collaborate when training and wellbeing overlap.')+coachTabs('both')+section('CHOOSE YOUR COACH',`<div class="coach-choice-grid"><article class="coach-choice-card"><div class="coach-choice-art"><img src="${A}coach-jack-portrait.webp" alt="Coach Jack — fitness training" loading="eager"><span>FITNESS & PERFORMANCE</span></div><div class="coach-choice-body"><div class="eyebrow">COACH JACK</div><h3>BUILD STRENGTH. TRAIN WITH PURPOSE.</h3><p>Ask about the approved RAVN South programmes, exercise technique, gradual progression, conditioning and recovery.</p>${btn('/coach/jack','Open Jack’s coaching chat')}<p class="mini">Training guidance · 23 fitness programmes</p></div></article><article class="coach-choice-card"><div class="coach-choice-art"><img src="${A}coach-jill-portrait.webp" alt="Coach Jill — mentality and habits" loading="eager"><span>MENTALITY & WELLBEING</span></div><div class="coach-choice-body"><div class="eyebrow">COACH JILL</div><h3>FIND YOUR WHY. BUILD LASTING HABITS.</h3><p>Explore your motivation, the Five Pillars, gym confidence, food habits, consistency and sustainable progress.</p>${btn('/coach/jill','Open Jill’s coaching chat')}<p class="mini">The Five Pillars · Reflection and wellbeing</p></div></article></div>`)+section('PRIVATE COACH CHAT',card(`<h3>Your conversations are separate</h3><p>Jack helps with practical training, while Jill helps with mentality and sustainable habits. Their private chats stay separate. If you choose Team Coaching, they can consult on your current question and share only the current answer, not the other chat history. This is an adults-only private AI pilot, not a live member service.</p><p class="mini">Team Coaching is optional: turn on collaboration for mixed-topic questions, or press Ask Both for a single question. Responses come from AI, not two human professionals. Both chats still require secure backend access.</p>`))}

const coachOpeners={jack:'Hi, I’m Coach Jack. Want help with training consistency, technique or planning a session?',jill:'Hi, I’m Coach Jill. What’s motivating you right now, and what feels hardest about staying consistent?'};
function jillCoachPage(){
 const kb=window.RAVN_JILL_KNOWLEDGE;
 const focus=[['Training confidence','I feel anxious walking into the gym'],['Nutrition habits','I feel guilty after eating'],['Energy and vitality','I feel exhausted and have no energy'],['Mental wellbeing','I have been feeling stressed']];
 const common=['I struggle with motivation','I missed a workout and feel I failed','How do the Five Pillars work?'];
 const sources=['NICE-PH49','NHS-ACTIVITY','NHS-EATWELL','NHS-MIND','WHO-STRESS','NLP-REVIEW'];
 const links=kb?sources.map(id=>kb.sources.find(s=>s.id===id)).filter(Boolean).map(s=>`<a class="jill-source" href="${s.url}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>`).join(''):'';
 return pageHero('COACH JILL','YOUR MENTALITY · YOUR CHOICES · YOUR PACE','Personal reflection for training, nutrition, vitality and emotional wellbeing — guided by the Five Pillars.')
 +coachTabs('jill')
 +section('TALK WITH COACH JILL',`<div class="jill-intro"><div class="coach-head"><img src="${A}coach-jill-portrait.webp" alt="Coach Jill"><div><h3>MENTALITY COACHING</h3><p>Every step counts. Even a difficult attempt can teach you something.</p></div></div><p class="mini">Coach Jill uses an AI service only after you choose to connect. She is not a therapist, doctor or dietitian. Your messages are sent to an AI provider to generate replies, but this website does not retain them on its server. Team Coaching is optional and shares only this question and its draft answer with the other AI coach, not your separate chat history. Avoid identifiable or sensitive details.</p></div><div class="grid cols2 jill-chat-grid">${card(`<div class="eyebrow">YOUR CONVERSATION <span id="jillServiceStatus" class="jill-service-state" aria-live="polite">Checking AI service…</span></div><div class="jill-auth" id="jillAuthPanel"><p class="mini">AI COACHING · Adults only. Your message will be processed by the AI provider. No website chat transcript is saved.</p><label class="checkline"><input id="jillConsent" type="checkbox"> I understand this is AI coaching, not therapy or medical advice, and agree to send my messages to the AI service.</label><label class="checkline"><input id="jillAdultConfirm" type="checkbox"> I confirm that I am 18 or older. This is an adults-only pilot.</label><div class="chatinput"><input id="jillAccessCode" type="password" maxlength="160" autocomplete="off" placeholder="Private pilot access code" aria-label="Pilot access code"><button class="btn" type="button" data-action="jill-access">Unlock Jill</button></div></div><div class="chat jill-chat" id="coachChat" role="log" aria-label="Coach Jill conversation" aria-live="polite"><div class="bubble">${esc(coachOpeners.jill)}</div></div><div class="chatinput"><input id="coachInput" maxlength="500" placeholder="What would you like help with?" aria-label="Write to Coach Jill"><button class="btn" data-action="coach" data-who="jill">Send</button></div><div class="coach-team-controls"><label class="checkline"><input type="checkbox" id="jillTeamOptIn"> Let Jill consult Jack automatically when a question also involves practical training or nutrition.</label><button class="btn-outline small" type="button" data-action="coach-both" data-who="jill">Ask Jack &amp; Jill together</button><p class="mini">Your choice. Only this question and Jill’s answer go to Jack; private chat histories are never combined.</p></div><div class="jill-quick-prompts">${focus.concat(common.map(x=>['',x])).map(([lbl,q])=>`<button class="btn-soft small" data-action="coach-quick" data-who="jill" data-question="${esc(q)}">${esc(lbl||q)}</button>`).join('')}</div><button class="btn-soft small" data-action="jill-reset" type="button">Start a fresh conversation</button> <button class="btn-soft small" data-action="jill-logout" type="button">Lock AI chat</button><p class="mini">If you need urgent mental-health support in England, call NHS 111 and select the mental-health option. In an emergency, call 999.</p>`)}${card(`<div class="eyebrow">HOW JILL WORKS</div><h3>Your Five Pillars, applied to real life</h3><p>Jill starts by understanding your reason, your circumstances and what you want to change. She asks one open question at a time and helps you choose an achievable next step.</p>${pillars.map(([n,t])=>`<div class="list-row"><strong>${esc(n)}</strong><span class="muted">${esc(t)}</span></div>`).join('')}<div class="line"></div><p class="mini">She can help with healthy habits and reflection. Coach Jack handles exercise technique. Medical issues, clinical nutrition and mental-health treatment need qualified professionals.</p><p class="mini">NLP-inspired exercises are optional. Jill never promises to treat illness or change memories.</p>`)}</div>`)
 +section('COACHING KNOWLEDGE & GUIDANCE',`${card(`<h3>RESEARCH-INFORMED GUIDANCE</h3><p>Built from your selected NLP material and public guidance from NICE, the NHS and WHO. We prioritise practical goal setting, supportive feedback, mental wellbeing, balanced food choices and sustainable exercise habits.</p><div class="jill-source-grid">${links}</div><p class="mini">NLP is not established as an effective clinical therapy. The source list is for transparency, not proof that every proposed NLP technique works.</p>`)}`);
}
function jackCoachPage(){
 const focus=[['Find a training plan','Which RAVN South programme suits a beginner with three days free?'],['Exercise technique','How can I improve my squat form safely?'],['Progressive overload','When should I increase the weight on my incline bench?'],['Recovery and vitality','How do I recover when I feel tired after training?']];
 const common=['How does Upper/Lower Mass Build work?','Can I train at home without equipment?','How do I improve my conditioning?'];
 const links=[['2026 ACSM resistance training guidance','https://acsm.org/science-spotlight-acsm-releases-new-position-stand-on-resistance-training/'],['NHS strength and flexibility','https://www.nhs.uk/live-well/exercise/how-to-improve-strength-flexibility/'],['NHS physical activity guidelines','https://www.nhs.uk/live-well/exercise/physical-activity-guidelines-for-adults-aged-19-to-64/'],['NHS warm-up guidance','https://www.nhs.uk/live-well/exercise/how-to-warm-up-before-exercising/'],['NHS Eatwell Guide','https://www.nhs.uk/live-well/eat-well/food-guidelines-and-food-labels/the-eatwell-guide/']];
 return `<section class="hero-custom jack-hero"><div class="wrap jack-hero-grid"><div class="mentality-hero-copy"><div class="eyebrow">RAVN SOUTH · DO IT. PROVE IT.</div><h1>COACH JACK<br><span>TRAIN WITH PURPOSE</span></h1><div class="eyebrow mentality-kicker">STRENGTH · TECHNIQUE · PROGRESSION</div><p class="lead">Practical fitness coaching that starts with your goals, experience, available time and equipment.</p><p>From your first controlled repetition to long-term strength, Jack helps you understand and use the RAVN South training programmes.</p><div class="mentality-hero-actions">${btn('/fitness-programmes','Browse Fitness Programmes')}${btn('/coaches','Meet both coaches',true)}</div><p class="mini">Private AI pilot · adults 18+ · not a substitute for an in-person coach or medical professional.</p></div><div class="jack-portrait"><img src="${A}coach-jack-portrait.webp" alt="Coach Jack in the approved RAVN South design"><div class="mentality-jill-name"><span>YOUR FITNESS COACH</span><strong>COACH JACK</strong><small>Build strength. Train with control. →</small></div></div></div></section>`
 +coachTabs('jack')
 +section('TRAIN WITH COACH JACK',`<div class="jill-intro"><div class="coach-head"><img src="${A}coach-jack-portrait.webp" alt="Coach Jack"><div><h3>FITNESS & PERFORMANCE COACHING</h3><p>Understand the movement, progress steadily, recover properly.</p></div></div><p class="mini">Jack uses an AI service when you choose to connect. He is not a medical professional and cannot see your form, diagnose injuries or read your actual member history. Please avoid entering personal or health details. Chat is processed by an AI provider and not stored on this site's server. Optional Team Coaching shares only the current question and first answer with Jill, never your separate chat history.</p></div><div class="grid cols2 jill-chat-grid">${card(`<div class="eyebrow">YOUR CONVERSATION <span id="jackServiceStatus" class="jill-service-state" aria-live="polite">Checking AI service…</span></div><div class="jill-auth" id="jackAuthPanel"><p class="mini">AI COACHING · Adults only · chats sent to the AI provider, not saved on this website's server.</p><label class="checkline"><input id="jackConsent" type="checkbox"> I understand this is AI fitness coaching, not individual medical or physiotherapy advice, and agree to send messages to the AI service.</label><label class="checkline"><input id="jackAdultConfirm" type="checkbox"> I confirm I am 18 or older.</label><div class="chatinput"><input id="jackAccessCode" type="password" maxlength="160" autocomplete="off" placeholder="Private pilot access code" aria-label="Coach Jack access code"><button class="btn" type="button" data-action="jack-access">Unlock Jack</button></div></div><div class="chat jill-chat" id="coachChat" role="log" aria-label="Coach Jack conversation" aria-live="polite"><div class="bubble">${esc(coachOpeners.jack)}</div></div><div class="chatinput"><input id="coachInput" maxlength="500" placeholder="Ask Jack about training or a programme…" aria-label="Write to Coach Jack"><button class="btn" data-action="coach" data-who="jack">Send</button></div><div class="coach-team-controls"><label class="checkline"><input type="checkbox" id="jackTeamOptIn"> Let Jack consult Jill automatically when a question includes motivation, confidence, food habits or recovery.</label><button class="btn-outline small" type="button" data-action="coach-both" data-who="jack">Ask Jack &amp; Jill together</button><p class="mini">Your choice. Only this question and Jack’s answer go to Jill; private chat histories are never combined.</p></div><div class="jill-quick-prompts">${focus.concat(common.map(q=>['',q])).map(([lbl,q])=>`<button class="btn-soft small" data-action="coach-quick" data-who="jack" data-question="${esc(q)}">${esc(lbl||q)}</button>`).join('')}</div><button class="btn-soft small" data-action="jack-reset">Start a fresh conversation</button> <button class="btn-soft small" data-action="jack-logout">Lock AI chat</button><p class="mini">Stop exercise for pain, dizziness or unusual symptoms; seek suitable medical help. Emergencies: 999 · urgent NHS advice: 111.</p>`)}${card(`<div class="eyebrow">HOW JACK WORKS</div><h3>Practical training, not quick fixes</h3><p>Jack bases his replies on the approved 23 Fitness Programmes and evidence-informed training principles. He asks about experience, goal, schedule and equipment before making suggestions.</p>${[['▣','TRAINING PROGRAMMES','Compare 23 existing options, from beginner to advanced'],['◆','TECHNIQUE','General movement guidance, without pretending to assess your form'],['↗','PROGRESSION','Load, reps, consistency and programme progression'],['◈','RECOVERY & NUTRITION','Sleep, manageable training and general food guidance']].map(([sym,t,d])=>`<div class="jack-feature"><span>${sym}</span><div><strong>${t}</strong><p>${d}</p></div></div>`).join('')}<div class="line"></div><p class="mini">Coach Jill handles deeper motivation, mental wellbeing and NLP-based reflection. Medical, injury and clinical nutrition questions need qualified support.</p><a class="btn-outline small" href="#/coach/jill">Talk with Coach Jill →</a>`)} </div>`)
 +section('PROGRAMMES & RESEARCH',`${card(`<h3>YOUR RAVN SOUTH TRAINING LIBRARY</h3><p>Jack uses existing programme names and exercise outlines, not invented RAVN plans. Advanced programmes are progressed towards, not unlocked simply by paying.</p><div class="grid cols3">${[['Beginner Strength','/fitness-programmes/programme/beginner-strength'],['Upper/Lower Mass Build','/fitness-programmes/programme/upper-lower-mass'],['Functional Strength','/fitness-programmes/programme/functional-strength']].map(([n,u])=>`<a class="jack-programme-link" href="#${u}">${esc(n)} →</a>`).join('')}</div><div class="jill-source-grid">${links.map(([t,url])=>`<a class="jill-source" href="${url}" target="_blank" rel="noopener noreferrer">${esc(t)} ↗</a>`).join('')}</div><p class="mini">Source links are publicly available reference material; general training advice is not medical clearance or an individual assessment.</p>`)} `);
}
function coachPage(who){if(!['jack','jill'].includes(who))return notFound();return who==='jill'?jillCoachPage():jackCoachPage()}
function settings(){return pageHero('SETTINGS','YOUR ACCOUNT. YOUR CONTROL.','Manage the preferences in your local development profile.')+section('YOUR PREFERENCES',`<div class="grid cols2">${card(`<h3>PRIVACY & NOTIFICATIONS</h3><label class="checkline"><input id="noticecheck" type="checkbox" ${s.notices?'checked':''}>Show progress notifications</label><label class="field"><span>Profile visibility</span><select id="settingsVisibility"><option value="members" ${s.visibility==='members'?'selected':''}>Members</option><option value="private" ${s.visibility==='private'?'selected':''}>Private</option></select></label><button class="btn" data-action="save-settings">Save preferences</button><p class="mini">Actual privacy enforcement requires authenticated server-side controls.</p>`)}${card(`<h3>DEMO DATA</h3><p>Your prototype progress, posts and preferences are stored in this browser. You can reset them at any time.</p><button class="btn-soft" data-action="reset">Reset my demo data</button><div class="line"></div><a class="btn-outline" href="#/privacy">Read privacy information</a>`)} </div>`) }
function results(){return pageHero('RESULTS & PROGRESS','YOUR PROGRESS HAS A STORY.','Recognise the actions that made a difference.')+section('YOUR JOURNEY SO FAR',`<div class="grid cols3">${card(`<div class="stat"><strong>${s.points}</strong><span>Points earned</span></div>`)}${card(`<div class="stat"><strong>${s.logs.length}</strong><span>Actions recorded</span></div>`)}${card(`<div class="stat"><strong>${level()}</strong><span>Current level</span></div>`)}</div><div class="line"></div>${card(`<h3>RECENT PROGRESS</h3>${s.logs.length?s.logs.slice(0,8).map(x=>`<div class="list-row"><span>${esc(x.label)}</span><span>+${x.points}</span></div>`).join(''):'Your first recorded action will appear here.'}`)}`,btn('/accountability','Add today’s progress')) }
function about(){return pageHero('OUR STORY','MORE THAN NUMBERS.','RAVN South is built around achievement, belonging, and sustainable personal growth.')+section('WHY WE BUILT THIS',`<div class="grid cols2">${card(`<h3>DO IT. PROVE IT.</h3><p>You don’t have to be perfect to make progress. Turning up, trying again and making one better decision all deserve recognition.</p><p>The Five Pillars are the foundation of training, nutrition and mentality across the community.</p>`)}${card(`<img class="banner-img" src="${A}jack-jill.webp" alt="Jack and Jill in the RAVN South brand hero"><h3 style="margin-top:16px">A JOURNEY YOU CAN BELONG TO</h3><p>A home for people improving their health, confidence, strength and habits at their own pace.</p>`)} </div>`)+section('MEET THE TEAM',card(`<h3>JACK & JILL</h3><p>Our two coaching characters support different parts of the same journey.</p>${btn('/coaches','Meet the coaches')}`)) }
function contact(){return pageHero('CONTACT','WE’RE HERE TO LISTEN.','Questions, feedback or ideas for RAVN South?')+section('SEND AN ENQUIRY',`<div style="max-width:720px">${card(`<label class="field"><span>Your name</span><input id="contactName" maxlength="80" placeholder="Your name"></label><label class="field"><span>Email</span><input id="contactEmail" type="email" placeholder="you@example.com"></label><label class="field"><span>Message</span><textarea id="contactMsg" rows="5" maxlength="2000" placeholder="How can we help?"></textarea></label><button class="btn" data-action="contact">Prepare enquiry</button><p class="mini">Until a contact service is connected, the demo will prepare an email in your email app rather than submit it to a server.</p>`)}</div>`) }
const faqData=[['Do I need to pay to use the community?','The planned Vault community experience is free for signed-up members. Paid tiers add enhanced member features.'],['Can I buy the highest training level?','No. Advanced programme access should be earned through effort, consistency and appropriate milestones, not simply purchased.'],['How does the Arena work?','Members earn legitimate points through training, nutrition, check-ins and challenges. The monthly leaderboard ranks overall achievement.'],['Are there prizes for first place?','No separate reward is planned. Recognition on the leaderboard is the reward.'],['Is this version live?','This is a prototype. Coach Jill has a separately configured AI pilot; accounts, payments and shared social data are not yet live.']];
function faq(){return pageHero('FREQUENTLY ASKED QUESTIONS','CLEAR ANSWERS.','Learn how the RAVN South experience works.')+section('YOUR QUESTIONS',`<div class="list">${faqData.map(([q,a])=>`<details class="card" style="padding:17px 22px"><summary style="cursor:pointer;font-weight:700">${q}</summary><p style="margin-top:16px">${a}</p></details>`).join('')}</div>`) }
function privacy(){return pageHero('PRIVACY','YOUR JOURNEY BELONGS TO YOU.','Understand how this prototype handles your information.')+section('PROTOTYPE PRIVACY',card(`<h3>Local demonstration only</h3><p>The demo saves your display name, actions and posts to localStorage on your own device so you can test navigation and progress. It has no backend user database and does not send your entries to other members. You can clear the demo through Settings.</p><p>Real authentication, privacy controls, moderation, data retention and a full legal privacy notice will be required before launch.</p>${btn('/settings','Manage local data',true)}`)) }
function terms(){return pageHero('TERMS & CONDITIONS','PROTOTYPE INFORMATION.','Information about this demonstration website.')+section('DEVELOPMENT PREVIEW',card(`<h3>Not yet a live membership platform</h3><p>All plans, social interactions, points and achievements in this version are demonstrations. No paid services or secure user accounts are active. Training and nutrition information is illustrative and not a substitute for tailored professional guidance.</p><p>Before public release, RAVN South will need approved Terms, Privacy Policy, safeguarding and community rules, and secure services.</p>`)) }
function notFound(){return pageHero('PAGE NOT FOUND','LET’S FIND YOUR WAY BACK.','The page you asked for is not part of this build.')+section('KEEP EXPLORING',card(`<h3>YOUR JOURNEY CONTINUES</h3>${btn('/','Back to home')}`))}

function stories(){return pageHero('MEMBER STORIES','PROGRESS DESERVES TO BE SEEN.','Share a short update about the steps that matter to you.')+section('YOUR STORIES',`${memberNotice()}<div class="grid cols2">${card(`<h3>SHARE A STORY</h3><label class="field"><span>Today’s story</span><textarea id="storyText" maxlength="300" rows="4" placeholder="A small win, a setback you learned from, or something you’re proud of..."></textarea></label><button class="btn" data-action="story">Add story</button><p class="mini">Visible only on this device during the demo; not posted to other members.</p>`)}${card(`<h3>STORYBOARD</h3>${s.stories.length?s.stories.slice(0,12).map(x=>`<div class="list-row"><div><span class="eyebrow">${esc(x.name)}</span><p>${esc(x.text)}</p><small>${new Date(x.at).toLocaleDateString('en-GB')}</small></div></div>`).join(''):'<p>Your first story will appear here.</p>'}`)}</div>`)}
const demoCommunity=['Hannah P.','Mark D.','Emma L.','James K.'];
function gifting(){return pageHero('GIFTING & RECOGNITION','ENCOURAGEMENT IS A STRENGTH.','Show support for effort, growth, kindness and consistency.')+section('SEND A GESTURE',`${memberNotice()}<div class="grid cols2">${card(`<h3>RECOGNISE A MEMBER</h3><label class="field"><span>Choose a demonstration member</span><select id="giftTo">${demoCommunity.map(n=>`<option>${n}</option>`).join('')}</select></label><label class="field"><span>Choose a gift</span><select id="giftType"><option>Consistency Star</option><option>Well Done</option><option>Great Encouragement</option><option>Keep Going</option></select></label><label class="field"><span>Your message</span><input id="giftMessage" maxlength="100" placeholder="You inspired me to keep showing up"></label><button class="btn" data-action="gift">Send demo gesture</button><p class="mini">This is a personal local demonstration. Nothing is delivered to another user.</p>`)}${card(`<h3>YOUR SENT GESTURES</h3>${s.gifts.length?s.gifts.map(x=>`<div class="list-row"><span><strong>✦ ${esc(x.type)}</strong> for ${esc(x.to)}<br><small>${esc(x.message)}</small></span><span class="mini">Demo</span></div>`).join(''):'<p>Celebrate someone’s progress with a first gesture.</p>'}`)}</div>`)}
function buddies(){return pageHero('TRAINING BUDDIES','YOU DO NOT HAVE TO DO IT ALONE.','Explore a future matching space based on shared interests, not appearance.')+section('FIND YOUR TRIBE',`${memberNotice()}<div class="grid cols3">${[['Strength training','Hannah P.','Build technique together'],['Everyday walking','Mark D.','Consistency matters more than speed'],['Nutrition accountability','Emma L.','Share meal-prep motivation']].map(([interest,name,detail])=>card(`<div class="symbol">♧</div><div class="eyebrow">${interest}</div><h3>${name}</h3><p>${detail}</p><button class="btn-outline" data-action="buddy" data-name="${name}">${s.buddies.includes(name)?'✓ Interest saved':'Save interest'}</button>`)).join('')}</div><p class="mini">People shown are illustrative. This feature does not connect or disclose anyone’s location.</p>`)}
function media(){return pageHero('COMMUNITY STORIES','SHARE YOUR JOURNEY.','Stories, progress and encouragement from The Vault.')+section('YOUR NEXT STEP',card(btn('/vault/feed','Open community feed')))}
function goals(){return pageHero('YOUR GOALS','SMALL STEPS. REAL DIRECTION.','Define achievable steps without sacrificing the balance of home, family, work and health.')+section('YOUR PERSONAL GOAL LIST',`${memberNotice()}<div class="grid cols2">${card(`<label class="field"><span>One achievable next step</span><input id="goalText" maxlength="150" placeholder="e.g. Get to the gym twice this week"></label><button class="btn" data-action="add-goal">Add a goal</button>`)}${card(`<h3>YOUR GOALS & REFLECTIONS</h3>${s.goals.length?s.goals.map((g,i)=>`<div class="list-row"><span>${esc(g)}</span><button class="btn-soft small" data-action="remove-goal" data-index="${i}" aria-label="Remove goal">Remove</button></div>`).join(''):'<p>Choose something you can realistically work towards.</p>'}`)}</div>`)}


async function updateJackStatus(){
 const el=$('#jackServiceStatus');if(!el)return;
 try{const r=await fetch('/api/jack/status',{credentials:'same-origin',cache:'no-store'}),data=await r.json();if(!el.isConnected)return;if(data.mode==='member'){const input=$('#jackAccessCode');if(input)input.hidden=true;const button=$('[data-action="jack-access"]');if(button)button.textContent='Enable AI coaching';}el.textContent=data.ready?'AI coaching service ready':'AI connection awaiting configuration';el.className='jill-service-state '+(data.ready?'ready':'unavailable');if(!data.ready){let t=$('#jackAuthPanel .mini');if(t)t.textContent='Live Coach Jack AI is not yet configured on this host. The training library can still be browsed.';}}
 catch{if(el.isConnected){el.textContent='AI server not connected';el.className='jill-service-state unavailable'}}
}
async function unlockJack(){
 const input=$('#jackAccessCode');if(!$('#jackConsent')?.checked)return toast('Please read and agree to the AI notice.');if(!$('#jackAdultConfirm')?.checked)return toast('The private pilot is for adults aged 18+.');if(!input?.value)return toast('Enter the private access code.');
 try{const r=await fetch('/api/jack/access',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-RAVN-Client':'1'},body:JSON.stringify({code:input.value,agree:true,adultConfirmed:true})});const data=await r.json();if(!r.ok)throw Error(data.error||'Unable to unlock Coach Jack');input.value='';$('#jackAuthPanel').hidden=true;const el=$('#jackServiceStatus');if(el){el.textContent='Private AI chat unlocked';el.className='jill-service-state ready'}toast('Coach Jack is connected.');}catch(e){toast(e.message||'AI connection failed')}
}
function addCoachCollaboration(box,data){
 const team=data?.collaboration;
 if(!team)return null;
 if(team.status==='joined' && team.reply){
  const other=team.coach==='jack'?'Coach Jack':'Coach Jill';
  const bubble=addJillBubble(box,team.reply);
  bubble.classList.add('coach-peer-bubble');
  const who=document.createElement('strong');who.className='coach-peer-label';who.textContent=other+' joined the conversation';
  bubble.prepend(who);
  if(team.pillar){const p=document.createElement('div');p.className='jill-answer-context';p.textContent=team.coach==='jill'?'Pillar: '+team.pillar:'Focus: '+team.pillar;bubble.append(p)}
  return other+': '+team.reply;
 }
 if(team.status==='safety'){const n=addJillBubble(box,'Safety guidance from the coaching team takes priority.');n.classList.add('jill-safety');return null}
 if(team.status==='unavailable'){const n=addJillBubble(box,'The other coach is unavailable right now. You can still continue with this coach.');n.classList.add('coach-peer-note');return null}
 return null;
}
async function sendJackMessage(message,mode='auto'){
 if(jackBusy)return;const box=$('#coachChat');if(!box)return;
 const inp=$('#coachInput');if(inp)inp.value='';addJillBubble(box,message,true);jackBusy=true;
 const pending=addJillBubble(box,'Coach Jack is thinking…');pending.setAttribute('role','status');
 const btn=$('[data-action="coach"][data-who="jack"]');if(btn)btn.disabled=true;
 try{const r=await fetch('/api/jack/chat',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-RAVN-Client':'1'},body:JSON.stringify({message,agree:Boolean($('#jackConsent')?.checked),history:jackHistory.slice(-12),collaborate:mode==='both'||Boolean($('#jackTeamOptIn')?.checked),teamMode:mode})});const data=await r.json();if(!r.ok)throw Error(data.error||'Jack could not connect.');pending.textContent=data.reply;
 if(['urgent','referral','age','unavailable'].includes(data.level))pending.classList.add('jill-safety');if(data.focus){const c=document.createElement('div');c.className='jill-answer-context';c.textContent=data.level==='ai'?'Pillar: '+data.focus:'Support and safeguarding';pending.append(c)}
 if(Array.isArray(data.sources)&&data.sources.length){const d=document.createElement('div');d.className='jill-citations';for(const x of data.sources.slice(0,2)){if(!/^https:\/\//.test(x.url))continue;const a=document.createElement('a');a.href=x.url;a.target='_blank';a.rel='noopener noreferrer';a.textContent='Guidance: '+x.title+' ↗';d.append(a)}pending.append(d)}
 const jackTeammate=addCoachCollaboration(box,data);
 if(data.level==='ai'){jackHistory.push({role:'user',content:message},{role:'assistant',content:(jackTeammate?'Coach Jack: '+data.reply+'\n'+jackTeammate:data.reply).slice(0,950)});jackHistory=jackHistory.slice(-12)}
 }catch(e){pending.textContent=(e.message||'Service unavailable')+' No scripted reply has been substituted.'}
 finally{jackBusy=false;if(btn?.isConnected)btn.disabled=false;box.scrollTop=box.scrollHeight}
}
async function updateJillStatus(){
 const el=$('#jillServiceStatus');if(!el)return;
 try{const response=await fetch('/api/jill/status',{credentials:'same-origin',cache:'no-store'});const data=await response.json();
 if(!el.isConnected)return;
 if(data.mode==='member'){const input=$('#jillAccessCode');if(input)input.hidden=true;const button=$('[data-action="jill-access"]');if(button)button.textContent='Enable AI coaching';}
 el.textContent=data.ready?'AI coaching service ready':'AI connection awaiting configuration';
 el.className='jill-service-state '+(data.ready?'ready':'unavailable');
 if(!data.ready){const panel=$('#jillAuthPanel');if(panel)panel.querySelector('.mini').textContent='The live AI service is not yet configured on this host. The rest of RAVN South remains available.';}
 }catch(e){if(el.isConnected){el.textContent='AI server not connected';el.className='jill-service-state unavailable'}}
}
async function unlockJill(){
 const input=$('#jillAccessCode'),consent=$('#jillConsent'),adult=$('#jillAdultConfirm');
 if(!consent?.checked)return toast('Please read and agree to the AI chat notice.');
 if(!adult?.checked)return toast('The private pilot is for adults aged 18 or over.');
 if(!input?.value)return toast('Enter the private access code.');
 try{const r=await fetch('/api/jill/access',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-RAVN-Client':'1'},body:JSON.stringify({code:input.value,agree:true,adultConfirmed:true})});const data=await r.json();
 if(!r.ok)throw Error(data.error||'Unable to unlock the chat');
 input.value='';$('#jillAuthPanel').hidden=true;let el=$('#jillServiceStatus');if(el){el.textContent='Private AI chat unlocked';el.className='jill-service-state ready'};
 toast('Coach Jill is connected.');
 }catch(e){toast(e.message||'AI connection failed')}
}
function addJillBubble(box,text,me=false){const el=document.createElement('div');el.className=me?'bubble me':'bubble';el.textContent=text;box.appendChild(el);box.scrollTop=box.scrollHeight;return el}
async function sendJillMessage(message,mode='auto'){
 if(jillBusy)return;
 const box=$('#coachChat');if(!box)return;
 const inp=$('#coachInput');if(inp)inp.value='';
 addJillBubble(box,message,true);jillBusy=true;
 const pending=addJillBubble(box,'Coach Jill is thinking…');pending.setAttribute('role','status');
 const btn=$('[data-action="coach"][data-who="jill"]');if(btn)btn.disabled=true;
 try{
  const r=await fetch('/api/jill/chat',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-RAVN-Client':'1'},body:JSON.stringify({message,agree:Boolean($('#jillConsent')?.checked),history:jillHistory.slice(-12),collaborate:mode==='both'||Boolean($('#jillTeamOptIn')?.checked),teamMode:mode})});
  const data=await r.json();if(!r.ok)throw Error(data.error||'Jill could not connect.');
  pending.textContent=data.reply;
  if(data.level==='urgent'||data.level==='referral'||data.level==='age'||data.level==='unavailable')pending.classList.add('jill-safety');
  if(data.pillar){const c=document.createElement('div');c.className='jill-answer-context';c.textContent=data.level==='ai'?'Pillar: '+data.pillar:'Support and safeguarding';pending.append(c)}
  if(Array.isArray(data.sources)&&data.sources.length){const d=document.createElement('div');d.className='jill-citations';for(const x of data.sources.slice(0,2)){if(!/^https:\/\//.test(x.url))continue;const a=document.createElement('a');a.href=x.url;a.target='_blank';a.rel='noopener noreferrer';a.textContent='Guidance: '+x.title+' ↗';d.append(a)}pending.append(d)}
  const jillTeammate=addCoachCollaboration(box,data);
  if(data.level==='ai'){jillHistory.push({role:'user',content:message},{role:'assistant',content:(jillTeammate?'Coach Jill: '+data.reply+'\n'+jillTeammate:data.reply).slice(0,950)});jillHistory=jillHistory.slice(-12)}
 }catch(e){pending.textContent=(e.message||'Service unavailable')+' No scripted reply has been substituted.'}
 finally{jillBusy=false;if(btn&&btn.isConnected)btn.disabled=false;box.scrollTop=box.scrollHeight}
}

function communityRestricted(p){return false}
function communityUnavailable(){return pageHero('COMING LATER','FREE COMMUNITY RELEASE','Training programmes, nutrition plans and the Arena are not available in this release.')+section('YOUR COMMUNITY IS FREE',card('<p>Share your story, connect with others and record your own goals in The Vault. No payment is required.</p>'+btn('/vault','Open The Vault')))}


function render(){const p=path();let content=communityRestricted(p)?communityUnavailable():p==='/test-access'?testAccess():p==='/'?home():p.startsWith('/fitness-programmes')?fitnessRoute(p):p==='/training'?training():p.startsWith('/training/')?trainingDetail(p.split('/')[2]):p==='/nutrition'?nutrition():p==='/nutrition/rotation'?rotation():p==='/nutrition/snacks'?nutritionSnacks():p==='/nutrition/shopping'?nutritionShopping():p.startsWith('/nutrition/plan/')?nutritionDetail(p.split('/')[3],p.split('/')[4],p.split('/')[5]):p==='/mentality'?mentality():p.startsWith('/mentality/')?pillarDetail(p.split('/')[2]):p==='/vault'?vault():p==='/vault/feed'?feed():p==='/vault/stories'?stories():p==='/vault/gifting'?gifting():p==='/vault/buddies'?buddies():p==='/arena'?arena():p==='/arena/leaderboard'?arenaLeaderboard():p==='/hall-of-fame'?hall():p==='/challenges'?challenges():p==='/achievements'?achievements():p==='/dashboard'?dashboard():p==='/accountability'?accountability():p==='/membership'?membership():p==='/login'?login():p==='/signup'?signup():(p==='/profile'||p==='/vault/profile')?profile():p==='/groups'?groups():p==='/messages'?messages():p==='/coaches'?coaches():p.startsWith('/coach/')?coachPage(p.split('/')[2]):p==='/settings'?settings():p==='/results'?results():p==='/goals'?goals():p==='/media'?media():p==='/about'?about():p==='/contact'?contact():p==='/faq'?faq():p==='/privacy'?privacy():p==='/terms'?terms():notFound();$('#app').innerHTML=header()+`<main id="main-content" class="page" tabindex="-1"><div class="test-notice"><strong>FULL SITE TEST</strong> · Demo data stays on this device. <a href="#/test-access">Test access &amp; all pages</a></div>${content}</main>`+footer();document.title='RAVN South · '+(p==='/'?'Home':p.split('/').filter(Boolean).map(x=>x.replace(/-/g,' ')).join(' / '));if(p==='/coach/jill')queueMicrotask(updateJillStatus);if(p==='/coach/jack')queueMicrotask(updateJackStatus);}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});
document.addEventListener('click',async e=>{let b=e.target.closest('[data-action]');if(!b)return;let action=b.dataset.action;if(action.startsWith('vp-')&&vpAction(b)){e.preventDefault();return}if(action.startsWith('f-')&&fAction(b)){e.preventDefault();return}let v=id=>document.getElementById(id)?.value||'';
if(action==='story'){let t=v('storyText').trim();if(!s.joined)return navto('/signup');if(t.length<3)return toast('Write a little more to share.');s.stories.unshift({name:s.name,text:t,at:new Date().toISOString()});save();render();toast('Story saved to this device');return}
if(action==='gift'){if(!s.joined)return navto('/signup');s.gifts.unshift({to:v('giftTo'),type:v('giftType'),message:v('giftMessage')});save();render();toast('Demo gesture saved');return}
if(action==='buddy'){if(!s.joined)return navto('/signup');let n=b.dataset.name;s.buddies=s.buddies.includes(n)?s.buddies.filter(x=>x!==n):[...s.buddies,n];save();render();toast('Matching preference saved locally');return}
if(action==='add-goal'){if(!s.joined)return navto('/signup');let t=v('goalText').trim();if(t.length<3)return toast('Add a short goal.');s.goals.unshift(t);save();render();toast('Goal saved');return}
if(action==='remove-goal'){s.goals.splice(Number(b.dataset.index),1);save();render();toast('Goal removed');return}
if(action==='menu'){$('#mainnav').classList.toggle('open');return}
if(action==='log'){logAction(b.dataset.key,Number(b.dataset.points),b.dataset.label,b.dataset.key==='challenge'?'month':'day');return}
if(action==='choose-program'){s.program=b.dataset.program;save();toast('Programme selected');render();return}
if(action==='leader-tab'){document.querySelectorAll('[data-action="leader-tab"]').forEach(el=>el.classList.toggle('active',el===b));$('#leaderrows').innerHTML=rankRows(b.dataset.period);return}
if(action==='post'){let text=v('posttext').trim();if(!s.joined)return navto('/login');if(text.length<3)return toast('Write a little more before posting.');s.posts.unshift({id:'p'+Date.now(),name:s.name,text,likes:0,age:'Just now'});save();toast('Post added to your local demo feed');render();return}
if(action==='like'){let id=b.dataset.id;s.likes=s.likes.includes(id)?s.likes.filter(x=>x!==id):[...s.likes,id];save();render();return}
if(action==='tier'){if(!s.joined)return navto('/login');if(b.dataset.tier==='Platinum')return toast('Platinum requires earned eligibility. It cannot be bought here.');s.tier=b.dataset.tier;save();toast('Demo tier updated — no payment taken');render();return}
if(action==='demo-login'||action==='signup'){let name=(action==='signup'?v('signupName'):v('demoName')).trim();if(name.length<2)return toast('Please enter a display name (at least 2 characters).');s.name=name;s.joined=true;if(action==='signup')s.goals=[v('signupGoal')];save();toast('Welcome to RAVN South');navto('/dashboard');return}
if(action==='save-profile'){let name=v('profileName').trim();if(name.length<2)return toast('Please enter a valid display name.');s.name=name;s.visibility=v('visibility');save();toast('Profile preferences saved');render();return}
if(action==='group'){let g=b.dataset.name;s.groups=s.groups.includes(g)?s.groups.filter(x=>x!==g):[...s.groups,g];save();toast(s.groups.includes(g)?'Joined your demo group':'Left demo group');render();return}
if(action==='message'){let msg=v('messageText').trim();if(!msg)return toast('Write a message.');s.messages.push({from:'You',text:msg});save();render();return}
if(action==='jill-reset'){jillHistory=[];render();return}
if(action==='jack-reset'){jackHistory=[];render();return}
if(action==='jack-access'){await unlockJack();return}
if(action==='jack-logout'){await fetch('/api/jack/logout',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-RAVN-Client':'1'},body:'{}'}).catch(()=>null);jackHistory=[];render();return}
if(action==='jill-access'){await unlockJill();return}
if(action==='jill-logout'){await fetch('/api/jill/logout',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-RAVN-Client':'1'},body:'{}'}).catch(()=>null);jillHistory=[];render();return}
if(action==='coach'||action==='coach-quick'||action==='coach-both'){
 let who=b.dataset.who,q=action==='coach-quick'?b.dataset.question:v('coachInput').trim(),mode=action==='coach-both'?'both':'auto';
 if(!q)return toast('Write a question.');
 if(who==='jill'){await sendJillMessage(q,mode);return}
 if(who==='jack'){await sendJackMessage(q,mode);return}
 toast('Please choose Coach Jack or Coach Jill.');return
}
if(action==='checkin'){let text=v('checkin').trim();if(!text)return toast('Write a short reflection first.');s.checkinText=text;save();logAction('checkin',5,'Accountability check-in');return}
if(action==='reflect'){let text=v('reflect').trim();if(text.length<3)return toast('Write one small step.');s.goals.unshift(b.dataset.pillar+': '+text);save();toast('Reflection saved to your local profile');return}
if(action==='save-settings'){s.notices=$('#noticecheck').checked;s.visibility=v('settingsVisibility');save();toast('Preferences saved');render();return}
if(action==='reset'){if(confirm('Clear your local RAVN South demo profile, posts and progress?')){s={...defaults};save();toast('Demo data reset');navto('/')}return}
if(action==='contact'){let name=v('contactName').trim(),mail=v('contactEmail').trim(),msg=v('contactMsg').trim();if(!name||!/^\S+@\S+\.\S+$/.test(mail)||!msg)return toast('Please add your name, valid email and message.');let subject=encodeURIComponent('RAVN South enquiry from '+name),body=encodeURIComponent(msg+'\n\nFrom: '+name+'\nEmail: '+mail);location.href='mailto:?subject='+subject+'&body='+body;toast('Email draft prepared — add the recipient address.');return}
});
document.addEventListener('input',e=>{if(e.target.dataset.fFilter==='search')fFilterChange(e.target)});
document.addEventListener('change',e=>{
 if(e.target.dataset.fFilter&&e.target.dataset.fFilter!=='search'){fFilterChange(e.target);return}
 if(e.target.matches('.f-exercise-check')){let el=e.target,key=today()+'|'+el.dataset.program,idx=Number(el.dataset.index);s.fitnessExercises=s.fitnessExercises||{};let arr=s.fitnessExercises[key]||[];s.fitnessExercises[key]=el.checked?[...new Set([...arr,idx])]:arr.filter(x=>x!==idx);save();return}
});
document.addEventListener('change',e=>{if(e.target.matches('.mealcheck')){let k=today()+'-'+e.target.dataset.meal;s.nutrition=e.target.checked?[...new Set([...s.nutrition,k])]:s.nutrition.filter(v=>v!==k);save();toast('Meal planner updated')}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='coachInput'){e.preventDefault();$('[data-action="coach"]')?.click()}if(e.key==='Enter'&&e.target.id==='messageText'){e.preventDefault();$('[data-action="message"]')?.click()}});
render();

function testAccess(){const links=[['Home','/'],['Dashboard','/dashboard'],['Training library','/fitness-programmes'],['Find a programme','/fitness-programmes/find'],['Training progress','/fitness-programmes/progress'],['Nutrition plans','/nutrition'],['Meal rotation','/nutrition/rotation'],['Shopping list','/nutrition/shopping'],['Five Pillars','/mentality'],['Coaches','/coaches'],['Coach Jack','/coach/jack'],['Coach Jill','/coach/jill'],['RAVN Vault','/vault'],['Community feed','/vault/feed'],['Stories','/vault/stories'],['Profile','/profile'],['Iron Match','/vault/buddies'],['Gifting','/vault/gifting'],['Groups','/groups'],['Messages','/messages'],['RAVN Arena','/arena'],['Leaderboard','/arena/leaderboard'],['Hall of Fame','/hall-of-fame'],['Challenges','/challenges'],['Accountability','/accountability'],['Achievements','/achievements'],['Results','/results'],['Goals','/goals'],['Membership','/membership'],['Settings','/settings'],['Media','/media'],['Our story','/about'],['Contact','/contact'],['FAQs','/faq']];return pageHero('YOUR FULL SITE TEST','EVERY AREA. ONE PLACE.','Explore the whole website and try the member experience.')+section('YOUR ACCESS',card('<button class="btn" data-action="owner-test">Enter as Chris — unlock all test areas</button><p>Test access is a local demo profile. No password or payment is needed. Posts, points and messages stay in this browser; messages do not reach other people. Live AI chat is not connected.</p>'))+section('ALL PAGES',`<div class="grid cols3">${links.map(([n,p])=>card('<h3>'+n+'</h3>'+btn(p,'Open',true))).join('')}</div>`)}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action="owner-test"]');if(!b)return;s.name='Chris';s.joined=true;s.ownerTest=true;s.tier='Owner test';save();navto('/dashboard');toast('Full test access enabled');});
